#include <iostream>
#include <type_traits>
template <typename T>
constexpr T add(T a, T b) { return a + b; }

template <typename T, std::enable_if_t<std::is_integral_v<T>, int> = 0>
constexpr T factorial(T n) { return (n == 0) ? 1 : n * factorial(n - 1); }

int main() {
  constexpr int sum = add(5, 3); //Compile-time evaluation
  constexpr int fact = factorial(5); //Compile-time evaluation
  std::cout << "Sum: " << sum << std::endl; //Output 8
  std::cout << "Factorial: " << fact << std::endl; //Output 120
  // Attempting to use factorial with a floating-point type will result in a compile-time error.
  return 0;
}
